export function portraitOffset(layout){const preferred=[[30,100],[-100,30],[100,-30],[-30,-100],[100,30],[-90,30],[100,0],[-90,0],[75,75],[-75,75],[75,-75],[-75,-75]];for(const radius of [90,75,60,45])for(let i=0;i<24;i++)preferred.push([Math.cos(i*Math.PI/12)*radius,Math.sin(i*Math.PI/12)*radius]);return preferred.find(([x,y])=>clearWalk(layout.spawn,{x:layout.spawn.x+x,y:layout.spawn.y+y},layout.nav))||[0,0];}
